import { mermaidLabel } from './mermaid-label.js';

// RF-601, RF-603, RF-508: the component diagram of the package's target architecture, a Mermaid
// flowchart generated by code from the planner's components; the model never writes Mermaid. One
// node per component in the planner's order, an arrow for each dependency on another component.
// Node ids are generated (`c1`, `c2`, ...), never taken from model text; every label goes through
// `mermaidLabel`; no node gets a click, a link or a style. The caller masks the names first.

export interface DiagramComponent {
  readonly name: string;
  readonly dependsOn: readonly string[];
}

// RF-601
export function componentDiagram(components: readonly DiagramComponent[]): string {
  const idOf = new Map<string, string>();
  const nodes = components.map((component, index) => {
    const id = `c${String(index + 1)}`;
    if (!idOf.has(component.name)) idOf.set(component.name, id);
    return `  ${id}["${mermaidLabel(component.name)}"]`;
  });
  const edges = components.flatMap((component, index) =>
    component.dependsOn.flatMap((name) => {
      const to = idOf.get(name);
      return to === undefined ? [] : [`  c${String(index + 1)} --> ${to}`];
    }),
  );
  return ['flowchart LR', ...nodes, ...edges].join('\n');
}
